// meta-ads-fetch
//
// Proxies the Meta (Facebook) Marketing Graph API for authenticated DigiCom
// users. Multi-tenant: each business owns N rows in
// public.meta_ads_connections; RLS restricts which ad account a caller can
// query. System User tokens (generated by the client inside their Business
// Manager) live in Postgres Vault, referenced by connection id via the
// SECURITY DEFINER RPC public.get_meta_ads_token(uuid) — granted to
// service_role only.
//
// Deploy convention (matches other functions in this project):
//   verify_jwt: false   — we do auth ourselves via supabase.auth.getUser()
//
// Error strategy: business / validation / Meta API errors return HTTP 200
// with { ok: false, error } so supabase.functions.invoke surfaces the real
// message. All user-facing error strings carry the [meta_v2] prefix so a
// stale deployment is obvious during debugging.
//
// Graph version pinned to v21.0.

import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';

const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? '';
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
const SUPABASE_ANON_KEY = Deno.env.get('SUPABASE_ANON_KEY') ?? '';

const GRAPH_BASE = 'https://graph.facebook.com/v21.0';

const CORS_HEADERS: HeadersInit = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

function jsonResponse(body: unknown, status = 200): Response {
    return new Response(JSON.stringify(body), {
        status,
        headers: { 'content-type': 'application/json', ...CORS_HEADERS },
    });
}

// ── Graph helpers ───────────────────────────────────────────────────────
type GraphError = {
    error?: { message?: string; type?: string; code?: number; error_subcode?: number };
};

async function graphGet(path: string, token: string, query: Record<string, string> = {}): Promise<any> {
    const params = new URLSearchParams({ ...query, access_token: token });
    const url = `${GRAPH_BASE}${path.startsWith('/') ? path : `/${path}`}?${params.toString()}`;
    const res = await fetch(url);
    const data = (await res.json()) as GraphError & Record<string, unknown>;
    if (!res.ok || data?.error) {
        throw mapGraphError(data, res.status);
    }
    return data;
}

async function graphPost(
    path: string,
    token: string,
    body: Record<string, unknown>,
    opts?: { form?: boolean }
): Promise<any> {
    const url = `${GRAPH_BASE}${path.startsWith('/') ? path : `/${path}`}`;
    const payload = { ...body, access_token: token };
    let req: RequestInit;
    if (opts?.form) {
        const form = new URLSearchParams();
        for (const [k, v] of Object.entries(payload)) {
            form.append(k, typeof v === 'string' ? v : JSON.stringify(v));
        }
        req = {
            method: 'POST',
            headers: { 'content-type': 'application/x-www-form-urlencoded' },
            body: form.toString(),
        };
    } else {
        req = {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify(payload),
        };
    }
    const res = await fetch(url, req);
    const data = (await res.json()) as GraphError & Record<string, unknown>;
    if (!res.ok || data?.error) throw mapGraphError(data, res.status);
    return data;
}

function mapGraphError(data: GraphError, status: number): Error {
    const err = data?.error;
    const code = err?.code;
    const msg = err?.message ?? `HTTP ${status}`;
    const userMsg = (err as any)?.error_user_msg ?? (err as any)?.error_user_title;
    const detail = userMsg ? `${msg} — ${userMsg}` : msg;
    if (code === 190) return new Error(`Meta: token expired or revoked — reconnect this account (${detail})`);
    if (code === 100) return new Error(`Meta: ${detail}`);
    if (code === 17 || code === 4 || code === 32 || code === 613) {
        return new Error(`Meta rate limit: ${detail}`);
    }
    return new Error(`Meta: ${detail}`);
}

function normalizeAdAccountId(raw: string): string {
    if (!raw) throw new Error('ad_account_id required');
    return raw.startsWith('act_') ? raw : `act_${raw.replace(/^act_/, '')}`;
}

// ── Token resolution per connection ─────────────────────────────────────
const TOKEN_CACHE = new Map<string, { token: string; at: number }>();
const TOKEN_TTL_MS = 10 * 60 * 1000;

async function getConnectionToken(
    admin: ReturnType<typeof createClient>,
    connection_id: string
): Promise<string> {
    const cached = TOKEN_CACHE.get(connection_id);
    if (cached && Date.now() - cached.at < TOKEN_TTL_MS) return cached.token;

    const { data, error } = await admin.rpc('get_meta_ads_token', { p_connection_id: connection_id });
    if (error) throw new Error(`vault rpc failed: ${error.message}`);
    if (!data) throw new Error('meta token missing for this connection');
    const token = typeof data === 'string' ? data : String(data);
    TOKEN_CACHE.set(connection_id, { token, at: Date.now() });
    return token;
}

// Re-check caller's RLS access to a connection via the user-scoped client.
async function assertCallerCanAccessConnection(
    userClient: ReturnType<typeof createClient>,
    connection_id: string
): Promise<{ ad_account_id: string; pixel_id: string | null; business_id: string }> {
    const { data, error } = await userClient
        .from('meta_ads_connections')
        .select('id, ad_account_id, pixel_id, "DigiCom Business"')
        .eq('id', connection_id)
        .limit(1)
        .maybeSingle();
    if (error) throw new Error(`rls check failed: ${error.message}`);
    if (!data) throw new Error('connection not found for this user');
    return {
        ad_account_id: (data as any).ad_account_id,
        pixel_id: (data as any).pixel_id,
        business_id: (data as any)['DigiCom Business'],
    };
}

// ── Insights helpers ────────────────────────────────────────────────────
const INSIGHT_FIELDS = [
    'spend',
    'impressions',
    'clicks',
    'ctr',
    'cpm',
    'cpc',
    'reach',
    'frequency',
    'actions',
    'action_values',
    'purchase_roas',
].join(',');

type DatePreset =
    | 'today'
    | 'yesterday'
    | 'last_7d'
    | 'last_14d'
    | 'last_28d'
    | 'last_30d'
    | 'last_90d'
    | 'this_month'
    | 'last_month'
    | 'maximum';

const DEFAULT_PRESET: DatePreset = 'last_28d';

function presetParams(preset?: string) {
    const p = (preset ?? DEFAULT_PRESET) as DatePreset;
    return { date_preset: p };
}

// ── Handler ─────────────────────────────────────────────────────────────
Deno.serve(async (req) => {
    if (req.method === 'OPTIONS') return new Response(null, { headers: CORS_HEADERS });
    if (req.method !== 'POST') {
        return jsonResponse({ ok: false, error: 'method not allowed' }, 405);
    }

    try {
        const authHeader = req.headers.get('authorization') ?? '';
        if (!authHeader.startsWith('Bearer ')) {
            return jsonResponse({ ok: false, error: 'missing authorization' });
        }

        const userClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
            global: { headers: { Authorization: authHeader } },
            auth: { persistSession: false },
        });
        const { data: userData } = await userClient.auth.getUser();
        if (!userData?.user) return jsonResponse({ ok: false, error: 'unauthorized' });

        const admin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
            auth: { persistSession: false },
        });

        const body = await req.json().catch(() => ({}));
        const action: string = body?.action;
        if (!action) return jsonResponse({ ok: false, error: 'action is required' });

        // ── Onboarding actions (no connection_id yet) ──────────────────
        if (action === 'verify_token') {
            try {
                const { token } = body;
                if (!token) throw new Error('token is required');
                // System User tokens often lack business_management, which is
                // what /me?fields=name needs. Use /me/adaccounts as the real
                // functional probe — this only needs ads_read and tells us
                // what the token can actually do.
                const accounts = await graphGet('/me/adaccounts', token, {
                    fields: 'id',
                    limit: '1',
                });
                const hasAny = Array.isArray(accounts.data) && accounts.data.length > 0;
                let account: any = null;
                if (body.ad_account_id) {
                    const act = normalizeAdAccountId(body.ad_account_id);
                    account = await graphGet(`/${act}`, token, {
                        fields: 'id,name,currency,timezone_name,account_status,business,amount_spent',
                    });
                }
                return jsonResponse({
                    ok: true,
                    has_ad_accounts: hasAny,
                    account,
                });
            } catch (e) {
                const msg = (e as Error).message;
                const tip = msg.includes('(#200)')
                    ? ' — the System User needs these scopes: ads_management, ads_read, business_management, read_insights. Regenerate the token and re-check those boxes.'
                    : '';
                return jsonResponse({ ok: false, error: `[meta_v2] ${msg}${tip}` });
            }
        }

        if (action === 'list_ad_accounts') {
            try {
                const { token } = body;
                if (!token) throw new Error('token is required');
                const res = await graphGet('/me/adaccounts', token, {
                    fields: 'id,name,currency,timezone_name,business,account_status,amount_spent,balance',
                    limit: '200',
                });
                return jsonResponse({ ok: true, accounts: res.data ?? [] });
            } catch (e) {
                return jsonResponse({ ok: false, error: `[meta_v2] ${(e as Error).message}` });
            }
        }

        if (action === 'list_pixels_for_token') {
            try {
                const { token, ad_account_id } = body;
                if (!token || !ad_account_id) throw new Error('token and ad_account_id required');
                const act = normalizeAdAccountId(ad_account_id);
                const res = await graphGet(`/${act}/adspixels`, token, {
                    fields: 'id,name,last_fired_time,code',
                });
                return jsonResponse({ ok: true, pixels: res.data ?? [] });
            } catch (e) {
                return jsonResponse({ ok: false, error: `[meta_v2] ${(e as Error).message}` });
            }
        }

        if (action === 'create_connection') {
            try {
                const {
                    token,
                    business_id,
                    ad_account_id,
                    display_name,
                    business_id_meta,
                    pixel_id,
                    is_default,
                    token_expires_at,
                } = body;
                if (!token || !business_id || !ad_account_id || !display_name) {
                    throw new Error('token, business_id, ad_account_id, display_name are required');
                }
                // Authorize: business admin of the SAME business the connection
                // is created for (previously any authenticated user could create
                // a connection + Vault secret against any business_id).
                const { data: prof } = await admin
                    .from('users').select('role, "DigiCom Business"').eq('id', userData.user.id).maybeSingle();
                if (!prof || !['super admin', 'admin'].includes(prof.role)
                    || !prof['DigiCom Business'] || prof['DigiCom Business'] !== business_id) {
                    return jsonResponse({ ok: false, error: 'forbidden' }, 403);
                }
                const act = normalizeAdAccountId(ad_account_id);
                // sanity probe
                await graphGet(`/${act}`, token, { fields: 'id,name' });

                const { data, error } = await admin.rpc('create_meta_ads_connection', {
                    p_business_id: business_id,
                    p_ad_account_id: act,
                    p_display_name: display_name,
                    p_token: token,
                    p_business_id_meta: business_id_meta ?? null,
                    p_pixel_id: pixel_id ?? null,
                    p_is_default: !!is_default,
                    p_created_by: userData.user.id,
                    p_token_expires_at: token_expires_at ?? null,
                });
                if (error) throw new Error(`create rpc failed: ${error.message}`);
                return jsonResponse({ ok: true, connection_id: data });
            } catch (e) {
                return jsonResponse({ ok: false, error: `[meta_v2] ${(e as Error).message}` });
            }
        }

        // ── Actions requiring an existing connection ───────────────────
        if (!body.connection_id) {
            return jsonResponse({ ok: false, error: `[meta_v2] connection_id is required for action ${action}` });
        }

        try {
            const conn = await assertCallerCanAccessConnection(userClient, body.connection_id);
            const token = await getConnectionToken(admin, body.connection_id);
            const act = normalizeAdAccountId(conn.ad_account_id);

            if (action === 'account_summary') {
                const data = await graphGet(`/${act}`, token, {
                    fields:
                        'id,name,currency,timezone_name,account_status,business,amount_spent,balance,spend_cap,funding_source_details',
                });
                return jsonResponse({ ok: true, account: data });
            }

            if (action === 'list_campaigns') {
                const preset = presetParams(body.date_preset);
                const res = await graphGet(`/${act}/campaigns`, token, {
                    fields: `id,name,status,effective_status,objective,daily_budget,lifetime_budget,budget_remaining,start_time,stop_time,created_time,updated_time,special_ad_categories,insights.date_preset(${preset.date_preset}){${INSIGHT_FIELDS}}`,
                    limit: body.limit ? String(body.limit) : '100',
                    ...(body.after ? { after: body.after } : {}),
                });
                return jsonResponse({ ok: true, campaigns: res.data ?? [], paging: res.paging ?? null });
            }

            if (action === 'list_adsets') {
                const preset = presetParams(body.date_preset);
                const path = body.campaign_id ? `/${body.campaign_id}/adsets` : `/${act}/adsets`;
                const res = await graphGet(path, token, {
                    fields: `id,name,status,effective_status,campaign_id,daily_budget,lifetime_budget,budget_remaining,billing_event,optimization_goal,bid_amount,start_time,end_time,targeting,insights.date_preset(${preset.date_preset}){${INSIGHT_FIELDS}}`,
                    limit: body.limit ? String(body.limit) : '100',
                    ...(body.after ? { after: body.after } : {}),
                });
                return jsonResponse({ ok: true, adsets: res.data ?? [], paging: res.paging ?? null });
            }

            if (action === 'list_ads') {
                const preset = presetParams(body.date_preset);
                const path = body.adset_id ? `/${body.adset_id}/ads` : `/${act}/ads`;
                const res = await graphGet(path, token, {
                    fields: `id,name,status,effective_status,adset_id,campaign_id,creative{id,thumbnail_url,image_url,title,body,object_story_spec},insights.date_preset(${preset.date_preset}){${INSIGHT_FIELDS}}`,
                    limit: body.limit ? String(body.limit) : '100',
                    ...(body.after ? { after: body.after } : {}),
                });
                return jsonResponse({ ok: true, ads: res.data ?? [], paging: res.paging ?? null });
            }

            if (action === 'get_insights') {
                const { level, object_id, date_preset, time_increment, breakdowns, metrics } = body;
                const id = object_id ?? act;
                const fields = metrics ?? INSIGHT_FIELDS;
                const params: Record<string, string> = {
                    level: level ?? 'account',
                    fields: Array.isArray(fields) ? fields.join(',') : String(fields),
                    date_preset: date_preset ?? DEFAULT_PRESET,
                    limit: '500',
                };
                if (time_increment) params.time_increment = String(time_increment);
                if (breakdowns) params.breakdowns = Array.isArray(breakdowns) ? breakdowns.join(',') : String(breakdowns);
                const res = await graphGet(`/${id}/insights`, token, params);
                return jsonResponse({ ok: true, rows: res.data ?? [], paging: res.paging ?? null });
            }

            if (action === 'update_status') {
                const { object_type, object_id, status } = body;
                if (!object_type || !object_id || !status) {
                    throw new Error('object_type, object_id, status are required');
                }
                if (!['ACTIVE', 'PAUSED', 'ARCHIVED', 'DELETED'].includes(status)) {
                    throw new Error(`unsupported status: ${status}`);
                }
                await graphPost(`/${object_id}`, token, { status }, { form: true });
                return jsonResponse({ ok: true, object_id, status });
            }

            if (action === 'update_budget') {
                const { object_id, daily_budget, lifetime_budget, bid_amount } = body;
                if (!object_id) throw new Error('object_id is required');
                const payload: Record<string, unknown> = {};
                if (daily_budget != null) payload.daily_budget = String(daily_budget);
                if (lifetime_budget != null) payload.lifetime_budget = String(lifetime_budget);
                if (bid_amount != null) payload.bid_amount = String(bid_amount);
                if (Object.keys(payload).length === 0) throw new Error('no budget fields supplied');
                await graphPost(`/${object_id}`, token, payload, { form: true });
                return jsonResponse({ ok: true, object_id, updated: payload });
            }

            if (action === 'create_campaign') {
                const {
                    name,
                    objective,
                    status,
                    special_ad_categories,
                    buying_type,
                    bid_strategy,
                    daily_budget,
                    lifetime_budget,
                } = body;
                if (!name || !objective) throw new Error('name and objective are required');
                const payload: Record<string, unknown> = {
                    name,
                    objective,
                    status: status ?? 'PAUSED',
                    special_ad_categories: special_ad_categories ?? [],
                    is_adset_budget_sharing_enabled: false,
                };
                if (buying_type) payload.buying_type = buying_type;
                if (bid_strategy) payload.bid_strategy = bid_strategy;
                if (daily_budget) payload.daily_budget = String(daily_budget);
                if (lifetime_budget) payload.lifetime_budget = String(lifetime_budget);
                const res = await graphPost(`/${act}/campaigns`, token, payload, { form: true });
                return jsonResponse({ ok: true, id: res.id });
            }

            if (action === 'create_adset') {
                const {
                    name,
                    campaign_id,
                    daily_budget,
                    lifetime_budget,
                    billing_event,
                    optimization_goal,
                    bid_strategy,
                    bid_amount,
                    targeting,
                    start_time,
                    end_time,
                    status,
                } = body;
                if (!name || !campaign_id || !targeting || !optimization_goal || !billing_event) {
                    throw new Error('name, campaign_id, targeting, optimization_goal, billing_event are required');
                }
                const payload: Record<string, unknown> = {
                    name,
                    campaign_id,
                    billing_event,
                    optimization_goal,
                    targeting,
                    status: status ?? 'PAUSED',
                    bid_strategy: bid_strategy ?? 'LOWEST_COST_WITHOUT_CAP',
                };
                if (daily_budget) payload.daily_budget = String(daily_budget);
                if (lifetime_budget) payload.lifetime_budget = String(lifetime_budget);
                if (bid_amount) payload.bid_amount = String(bid_amount);
                if (start_time) payload.start_time = start_time;
                if (end_time) payload.end_time = end_time;
                const res = await graphPost(`/${act}/adsets`, token, payload, { form: true });
                return jsonResponse({ ok: true, id: res.id });
            }

            if (action === 'create_ad') {
                const { name, adset_id, creative, status } = body;
                if (!name || !adset_id || !creative) throw new Error('name, adset_id, creative are required');
                const payload = {
                    name,
                    adset_id,
                    creative,
                    status: status ?? 'PAUSED',
                };
                const res = await graphPost(`/${act}/ads`, token, payload, { form: true });
                return jsonResponse({ ok: true, id: res.id });
            }

            if (action === 'upload_image_from_url') {
                const { image_url } = body;
                if (!image_url) throw new Error('image_url is required');
                const res = await graphPost(`/${act}/adimages`, token, { url: image_url }, { form: true });
                return jsonResponse({ ok: true, images: res.images ?? res });
            }

            if (action === 'list_pages') {
                const res = await graphGet('/me/accounts', token, {
                    fields: 'id,name,category,picture',
                    limit: '50',
                });
                return jsonResponse({ ok: true, pages: res.data ?? [] });
            }

            if (action === 'list_custom_audiences') {
                const res = await graphGet(`/${act}/customaudiences`, token, {
                    fields: 'id,name,subtype,approximate_count_lower_bound,approximate_count_upper_bound,time_updated',
                    limit: '100',
                });
                return jsonResponse({ ok: true, audiences: res.data ?? [] });
            }

            // ── Pixel actions ───────────────────────────────────────
            if (action === 'get_pixel_overview') {
                const pixel_id = body.pixel_id ?? conn.pixel_id;
                if (!pixel_id) throw new Error('pixel_id is required (none saved on this connection)');
                const pixel = await graphGet(`/${pixel_id}`, token, {
                    fields: 'id,name,last_fired_time,code,creation_time,data_use_setting,owner_business',
                });
                return jsonResponse({ ok: true, pixel });
            }

            if (action === 'get_pixel_events_by_type') {
                const pixel_id = body.pixel_id ?? conn.pixel_id;
                if (!pixel_id) throw new Error('pixel_id is required');
                const preset = body.date_preset ?? DEFAULT_PRESET;
                // Pixel stats come back as [{ aggregation, data: [{ value, count }]}]
                const res = await graphGet(`/${pixel_id}/stats`, token, {
                    aggregation: 'event',
                    start_time: isoDaysAgo(presetToDays(preset)),
                });
                return jsonResponse({ ok: true, stats: res.data ?? [] });
            }

            if (action === 'get_pixel_timeseries') {
                const pixel_id = body.pixel_id ?? conn.pixel_id;
                if (!pixel_id) throw new Error('pixel_id is required');
                const preset = body.date_preset ?? DEFAULT_PRESET;
                const res = await graphGet(`/${pixel_id}/stats`, token, {
                    aggregation: 'event_time',
                    start_time: isoDaysAgo(presetToDays(preset)),
                });
                return jsonResponse({ ok: true, stats: res.data ?? [] });
            }

            if (action === 'mark_verified') {
                // Lightweight ping used by the UI to refresh the cached health
                await graphGet(`/${act}`, token, { fields: 'id' });
                const { error } = await admin
                    .from('meta_ads_connections')
                    .update({
                        verification_status: 'verified',
                        verification_error: null,
                        last_verified_at: new Date().toISOString(),
                    })
                    .eq('id', body.connection_id);
                if (error) throw new Error(error.message);
                return jsonResponse({ ok: true });
            }

            return jsonResponse({ ok: false, error: `[meta_v2] unknown action: ${action}` });
        } catch (e) {
            return jsonResponse({ ok: false, error: `[meta_v2] ${(e as Error).message}` });
        }
    } catch (e) {
        console.error('[meta-ads-fetch] fatal', e);
        return jsonResponse({ ok: false, error: `[meta_v2] ${(e as Error).message}` }, 500);
    }
});

function presetToDays(preset: string): number {
    switch (preset) {
        case 'today':
        case 'yesterday':
            return 1;
        case 'last_7d':
            return 7;
        case 'last_14d':
            return 14;
        case 'last_30d':
        case 'last_28d':
            return 30;
        case 'last_90d':
            return 90;
        case 'this_month':
        case 'last_month':
            return 31;
        default:
            return 28;
    }
}

function isoDaysAgo(days: number): string {
    const d = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
    return Math.floor(d.getTime() / 1000).toString();
}
